-- Generated executable query. Run with SQLite against indus_weave.db.
WITH months(month_start,month_end) AS (VALUES ('2026-04-01','2026-04-30'),('2026-05-01','2026-05-31'),('2026-06-01','2026-06-30'),('2026-07-01','2026-07-31'),('2026-08-01','2026-08-31'),('2026-09-01','2026-09-30')) SELECT m.month_start,d.plant_name,d.department_name,COUNT(DISTINCT e.emp_id) headcount FROM months m JOIN dim_employee e ON e.valid_from<=m.month_end AND e.valid_to>=m.month_end JOIN dim_department d ON d.department_key=e.department_key JOIN staging_employee_entitlement se ON se.emp_id=e.emp_id WHERE e.hire_date<=m.month_end AND (e.separation_date='' OR e.separation_date IS NULL OR e.separation_date>m.month_end) GROUP BY m.month_start,d.plant_name,d.department_name ORDER BY m.month_start,d.plant_name,d.department_name;
